UPDATE puntos_aislamiento AS pa
SET maquina_id = m.id
FROM maquinas AS m
WHERE pa.maquina_id IS NULL
  AND m.nombre = 'DESPALETIZADORA L1'
  AND pa.id_visual IN ('PM-DEPA-E1', 'PM-DEPA-N1', 'PM-DEPA-L1', 'PM-DEPA-E2');

