UPDATE registros_checklist AS rc
SET maquina_id = pa.maquina_id
FROM puntos_aislamiento AS pa
WHERE rc.maquina_id IS NULL
  AND rc.punto_id = pa.id
  AND pa.maquina_id IS NOT NULL;

